-- AD Me core: all authorization derives from database roles, never JWT user metadata.
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade, role text not null check(role in ('brand','creator','admin')), name text not null, created_at timestamptz not null default now());
create function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from profiles where id=auth.uid() and role='admin'); $$;
create function public.my_role() returns text language sql stable security definer set search_path=public as $$ select role from profiles where id=auth.uid(); $$;
create function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into profiles(id,role,name) values(new.id,case when new.raw_user_meta_data->>'role'='creator' then 'creator' else 'brand' end,left(coalesce(new.raw_user_meta_data->>'name','새 사용자'),80));return new;end $$;
create trigger adme_user_created after insert on auth.users for each row execute function public.handle_new_user();
create table public.creators(id text primary key,owner_id uuid unique references profiles(id),published boolean not null default false,profile jsonb not null,created_at timestamptz not null default now());
create table public.campaigns(id uuid primary key default gen_random_uuid(),owner_id uuid references profiles(id),brief jsonb not null,status text not null default 'draft' check(status in ('draft','published','closed')),is_demo boolean not null default false,seed_id text unique,created_at timestamptz not null default now());
create table public.saved_creators(owner_id uuid not null references profiles(id) on delete cascade,creator_id text not null references creators(id) on delete cascade,created_at timestamptz not null default now(),primary key(owner_id,creator_id));
create table public.proposals(id uuid primary key default gen_random_uuid(),campaign_id uuid not null references campaigns(id),creator_id text not null references creators(id),brand_id uuid not null references profiles(id),creator_user_id uuid not null references profiles(id),kind text not null check(kind in ('proposal','application')),status text not null default 'pending' check(status in ('pending','accepted','rejected','submitted','revision_requested','completed')),brief text not null check(length(brief) between 10 and 3000),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(campaign_id,creator_id));
create table public.messages(id uuid primary key default gen_random_uuid(),proposal_id uuid not null references proposals(id),sender_id uuid not null references profiles(id),body text not null check(length(body) between 1 and 3000),kind text not null check(kind in ('message','deliverable')),url text check(url is null or url like 'https://%'),created_at timestamptz not null default now());
create table public.reports(id uuid primary key default gen_random_uuid(),reporter_id uuid not null references profiles(id),creator_id text not null references creators(id),reason text not null check(length(reason) between 10 and 2000),source_url text not null check(source_url like 'https://%'),status text not null default 'pending' check(status in ('pending','reviewed','dismissed')),created_at timestamptz not null default now());
create table public.audit_log(id bigint generated always as identity primary key,actor_id uuid references profiles(id),entity_id text not null,action text not null,created_at timestamptz not null default now());
create table public.ad_collaborations(id text primary key,creator_id text not null references creators(id),data jsonb not null,is_demo boolean not null default true,verified_at timestamptz,source_url text);
create table public.products(sku text primary key,name text not null,amount integer not null check(amount>0),role text not null check(role in ('brand','creator')),days integer not null default 30,credits integer not null default 0);
insert into products values('brand_pro','Brand Pro',49000,'brand',30,0),('agency','Agency',149000,'brand',30,0),('creator_hot','Creator HOT',9900,'creator',30,0),('ai_credits','AI 분석 20 크레딧',4900,'brand',30,20);
create table public.orders(id uuid primary key default gen_random_uuid(),owner_id uuid not null references profiles(id),sku text not null references products(sku),amount integer not null check(amount>0),status text not null default 'pending' check(status in ('pending','paid','failed','cancelled')),payment_key text unique,created_at timestamptz not null default now(),paid_at timestamptz);
create table public.entitlements(id uuid primary key default gen_random_uuid(),owner_id uuid not null references profiles(id),order_id uuid not null unique references orders(id),sku text not null references products(sku),starts_at timestamptz not null default now(),expires_at timestamptz not null,credits integer not null default 0);
create index on campaigns(owner_id);create index on proposals(brand_id);create index on proposals(creator_user_id);create index on messages(proposal_id);create index on orders(owner_id);create index on entitlements(owner_id,expires_at);create index on reports(reporter_id);
alter table profiles enable row level security;alter table creators enable row level security;alter table campaigns enable row level security;alter table saved_creators enable row level security;alter table proposals enable row level security;alter table messages enable row level security;alter table reports enable row level security;alter table audit_log enable row level security;alter table ad_collaborations enable row level security;alter table products enable row level security;alter table orders enable row level security;alter table entitlements enable row level security;
create policy profiles_read on profiles for select using(id=auth.uid() or is_admin());
create policy profiles_edit on profiles for update using(id=auth.uid()) with check(id=auth.uid());
revoke update on profiles from authenticated; grant update(name) on profiles to authenticated;
create policy creators_read on creators for select using(published or owner_id=auth.uid() or is_admin());
create policy creators_insert on creators for insert with check(owner_id=auth.uid() and my_role()='creator' and id='user-'||auth.uid()::text);
create policy creators_update on creators for update using(owner_id=auth.uid() or is_admin()) with check(owner_id=auth.uid() or is_admin());
create policy creators_delete on creators for delete using(owner_id=auth.uid());
create policy campaigns_read on campaigns for select using(status='published' or owner_id=auth.uid() or is_admin());
create policy campaigns_insert on campaigns for insert with check(owner_id=auth.uid() and my_role()='brand' and not is_demo and seed_id is null);
create policy campaigns_update on campaigns for update using(owner_id=auth.uid() and my_role()='brand') with check(owner_id=auth.uid() and not is_demo and seed_id is null);
create policy campaigns_delete on campaigns for delete using(owner_id=auth.uid());
create policy saved_own on saved_creators for all using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy proposals_read on proposals for select using(auth.uid() in (brand_id,creator_user_id) or is_admin());
create policy proposals_insert on proposals for insert with check(status='pending' and exists(select 1 from campaigns ca join creators cr on cr.id=creator_id where ca.id=campaign_id and ca.owner_id=brand_id and cr.owner_id=creator_user_id and cr.published and ((kind='proposal' and brand_id=auth.uid() and my_role()='brand') or (kind='application' and creator_user_id=auth.uid() and my_role()='creator' and ca.status='published'))));
-- Proposal updates only through the locked state-transition function.
create policy messages_read on messages for select using(exists(select 1 from proposals p where p.id=proposal_id and auth.uid() in (p.brand_id,p.creator_user_id)));
create policy messages_insert on messages for insert with check(sender_id=auth.uid() and exists(select 1 from proposals p where p.id=proposal_id and auth.uid() in (p.brand_id,p.creator_user_id) and p.status<>'rejected' and (kind='message' or (p.creator_user_id=auth.uid() and p.status in ('accepted','revision_requested')))));
create policy reports_read on reports for select using(reporter_id=auth.uid() or is_admin());
create policy reports_insert on reports for insert with check(reporter_id=auth.uid() and status='pending');
create policy audit_read on audit_log for select using(is_admin());
create policy ads_read on ad_collaborations for select using(is_demo or (verified_at is not null and source_url like 'https://%'));
create policy products_read on products for select using(true);
create policy orders_read on orders for select using(owner_id=auth.uid() or is_admin());
create policy entitlements_read on entitlements for select using(owner_id=auth.uid() or is_admin());
create function public.transition_proposal(p_id uuid,p_action text) returns text language plpgsql security definer set search_path=public as $$ declare p proposals; r text;begin select * into p from proposals where id=p_id for update;if not found or auth.uid() not in (p.brand_id,p.creator_user_id) then raise exception 'forbidden';end if;r:=case when auth.uid()=p.brand_id then 'brand' else 'creator' end;if not ((p.status='pending' and p_action in ('accepted','rejected') and r=case when p.kind='proposal' then 'creator' else 'brand' end) or (p.status in ('accepted','revision_requested') and p_action='submitted' and r='creator' and exists(select 1 from messages where proposal_id=p.id and kind='deliverable')) or (p.status='submitted' and p_action in ('completed','revision_requested') and r='brand')) then raise exception 'invalid transition';end if;update proposals set status=p_action,updated_at=now() where id=p.id;insert into audit_log(actor_id,entity_id,action) values(auth.uid(),p.id::text,p_action);return p_action;end $$;
create function public.create_test_order(p_sku text) returns orders language plpgsql security definer set search_path=public as $$ declare item products; o orders;begin select * into item from products where sku=p_sku;if not found or auth.uid() is null or my_role()<>item.role then raise exception 'invalid product or role';end if;if (select count(*) from orders where owner_id=auth.uid() and created_at>now()-interval '1 hour')>=20 then raise exception 'order rate limit';end if;insert into orders(owner_id,sku,amount) values(auth.uid(),item.sku,item.amount) returning * into o;return o;end $$;
create function public.finalize_test_order(p_order uuid,p_owner uuid,p_payment_key text,p_amount integer) returns uuid language plpgsql security definer set search_path=public as $$ declare o orders; item products; entitlement_id uuid;begin select * into o from orders where id=p_order for update;if not found or o.owner_id<>p_owner or o.amount<>p_amount then raise exception 'order mismatch';end if;if o.status='paid' then if o.payment_key<>p_payment_key then raise exception 'payment mismatch';end if;select id into entitlement_id from entitlements where order_id=o.id;return entitlement_id;end if;if o.status<>'pending' then raise exception 'invalid order status';end if;select * into item from products where sku=o.sku;update orders set status='paid',payment_key=p_payment_key,paid_at=now() where id=o.id;insert into entitlements(owner_id,order_id,sku,expires_at,credits) values(o.owner_id,o.id,o.sku,now()+make_interval(days=>item.days),item.credits) returning id into entitlement_id;return entitlement_id;end $$;
revoke all on function public.finalize_test_order(uuid,uuid,text,integer) from public,anon,authenticated;grant execute on function public.finalize_test_order(uuid,uuid,text,integer) to service_role;
revoke all on function public.transition_proposal(uuid,text),public.create_test_order(text) from public,anon;grant execute on function public.transition_proposal(uuid,text),public.create_test_order(text) to authenticated;
revoke all on function public.handle_new_user() from public,anon,authenticated;
create function public.review_report(p_id uuid,p_status text) returns void language plpgsql security definer set search_path=public as $$ begin if not is_admin() or p_status not in ('reviewed','dismissed') then raise exception 'forbidden';end if;update reports set status=p_status where id=p_id;insert into audit_log(actor_id,entity_id,action) values(auth.uid(),p_id::text,'report:'||p_status);end $$;
revoke all on function public.review_report(uuid,text) from public,anon;grant execute on function public.review_report(uuid,text) to authenticated;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('portfolios','portfolios',false,5242880,array['image/jpeg','image/png','image/webp','application/pdf']);
create policy portfolio_select on storage.objects for select using(bucket_id='portfolios' and (storage.foldername(name))[1]=auth.uid()::text);
create policy portfolio_insert on storage.objects for insert with check(bucket_id='portfolios' and (storage.foldername(name))[1]=auth.uid()::text);
create policy portfolio_delete on storage.objects for delete using(bucket_id='portfolios' and (storage.foldername(name))[1]=auth.uid()::text);
